WITH flattened AS (SELECT id, effective_from, tier_value FROM price_tiers LATERAL VIEW EXPLODE(discounts) li AS tier_value), cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), effective_from) days_since_effective_from FROM flattened WHERE effective_from >= DATE '2024-06-02' AND tier_value >= 54), scored AS (SELECT *, RANK() OVER w_ordered tier_value_rank, DENSE_RANK() OVER (ORDER BY tier_value) tier_value_dense_rank, DENSE_RANK() OVER (ORDER BY tier_value DESC NULLS FIRST) tier_value_dense_rank_2 FROM cleaned WINDOW w_ordered AS (ORDER BY tier_value NULLS LAST)), with_windows AS (SELECT *, PERCENT_RANK() OVER w_running days_since_effective_from_percent_rank, CUME_DIST() OVER (ORDER BY tier_value_dense_rank_2 NULLS LAST) tier_value_dense_rank_2_cume_dist, CUME_DIST() OVER w_running days_since_effective_from_cume_dist, PERCENT_RANK() OVER (ORDER BY tier_value_rank DESC) tier_value_rank_percent_rank FROM scored WINDOW w_running AS (ORDER BY days_since_effective_from NULLS LAST)) SELECT CASE WHEN tier_value_rank >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END AS tier_value_rank_tier, DATE_TRUNC('MONTH', effective_from) AS activity_month, COUNT(*) AS event_count, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(days_since_effective_from_cume_dist, ARRAY(0.25, 0.5, 0.75)) AS days_since_effective_from_cume_dist_quartiles FROM with_windows GROUP BY CASE WHEN tier_value_rank >= 7 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('MONTH', effective_from) ORDER BY tier_value_rank_tier DESC
